// The comment rules' Reviews section defines this review. The wait prints its
// template; merge accepts only a completed review of the current head.
export const reviewsSection = ".repo-standards/rules/comments.md#reviews";

export const reviewTemplate = (head) => [
  "> _This was generated by AI._",
  "",
  `Head: ${head}`,
  "Standards: <the Standards review's actual outcome>",
  "Spec: <the Spec review's actual outcome>",
  "Fixed: <Nothing, or what this round fixed>",
  "Findings: <None, or one list item per finding below>",
  "- `<path>:<line>` <the finding>",
];

const fields = ["Head", "Standards", "Spec", "Fixed", "Findings"];
const field = new RegExp(`^(${fields.join("|")}):[\\t ]*(.*?)[\\t ]*$`);
const item = /^[-*][\t ]+/;
// A finding starts with its file and line, optionally in a code span.
const located = /^[-*][\t ]+(`?)[^\s`<>]+:\d+(?:-\d+)?\1[\t ]+\S/;

const placeholders = reviewTemplate("").filter((line) => line.includes("<"));
const completed = (value) =>
  Boolean(value?.trim()) &&
  !/^(?:TODO|TBD|placeholder|_?No response_?|<[^>]*>|\[[^\]]*\]|\{[^}]*\})[.!]?$/i.test(
    value,
  ) &&
  !placeholders.some((line) => value.includes(line.slice(line.indexOf("<"))));

// The head a review names, when it names one full SHA; review-agnostic callers
// then check completeness against it.
export function reviewedHead(body) {
  if (typeof body !== "string") return null;
  const heads = body
    .split(/\r?\n/)
    .map((line) => field.exec(line))
    .filter((match) => match?.[1] === "Head");
  return heads.length === 1 && /^[0-9a-f]{40}$/.test(heads[0][2])
    ? heads[0][2]
    : null;
}

export function completeReview(body, head) {
  if (typeof body !== "string") return false;
  // The review is plain text, never a quoted example or HTML comment.
  if (/^\s*(?:`{3,}|~{3,})/m.test(body) || body.includes("<!--")) return false;
  const lines = body.split(/\r?\n/);
  const entries = lines.flatMap((line, index) => {
    const match = field.exec(line);
    return match ? [{ key: match[1], value: match[2], index }] : [];
  });
  if (
    entries.length !== fields.length ||
    new Set(entries.map(({ key }) => key)).size !== fields.length
  )
    return false;
  const byField = Object.fromEntries(entries.map((entry) => [entry.key, entry]));
  const next = entries.find(({ index }) => index > byField.Findings.index);
  const findings = lines
    .slice(byField.Findings.index + 1, next?.index)
    .filter((line) => item.test(line));
  const findingsComplete = byField.Findings.value
    ? /^None\.?$/i.test(byField.Findings.value) && findings.length === 0
    : findings.length > 0 && findings.every((line) => located.test(line));
  return (
    byField.Head.value === head &&
    ["Standards", "Spec", "Fixed"].every((key) =>
      completed(byField[key].value),
    ) &&
    findingsComplete
  );
}
